export const escapeHtml=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function safeUrl(v){try{const u=new URL(v);return ['https:','http:'].includes(u.protocol)?u.href:''}catch{return ''}}
export function ordered(items){return [...items].sort((a,b)=>b.published_at.localeCompare(a.published_at)||a.id.localeCompare(b.id))}
export function filterNews(items,{query='',material='',kind='',month='',includeBackground=false}={}){const q=query.trim().toLocaleLowerCase();return ordered(items.filter(x=>(includeBackground||x.focus!=='企业与产线')&&(!material||x.materials.includes(material))&&(!kind||x.kind===kind)&&(!month||x.published_at.startsWith(month))&&(!q||[x.title,x.summary,x.source_name,...x.materials].join(' ').toLocaleLowerCase().includes(q))))}
export function newsCard(x,saved=false){const e=escapeHtml,url=safeUrl(x.url);return `<article class="news-item"><div class="news-meta"><time datetime="${e(x.published_at)}">${e(x.published_at)}</time><span>·</span><span>${e(x.kind)}</span><span class="news-source">${e(x.source_name)}</span></div><h3>${e(x.title)}</h3><p>${e(x.summary)}</p><div class="news-bottom"><button class="btn" data-news-save="${e(x.id)}" aria-pressed="${saved}">${saved?'★ 已收藏':'☆ 收藏'}</button><div class="news-tags">${x.materials.map(m=>linkedTags.has(m.toUpperCase())?`<button type="button" data-material-tag="${e(m)}" aria-label="查看${e(m)}材料资料">${e(m)} ↗</button>`:`<span>${e(m)}</span>`).join('')}</div>${url?`<a href="${e(url)}" target="_blank" rel="noopener noreferrer" aria-label="阅读原文：${e(x.title)}">阅读原文 ↗</a>`:''}</div></article>`}
